const rest: S6 = { es: 'en reposo', en: 'at rest', fr: 'au repos', de: 'in Ruhe', it: 'a riposo', pt: 'em repouso' };
const named = (n: S6, f: string): S6 => Object.fromEntries((Object.keys(n) as Lang[]).map((l) => [l, `${n[l]}: ${f}`])) as S6;
const resting = (f: string): S6 => Object.fromEntries((Object.keys(rest) as Lang[]).map((l) => [l, `${f} (${rest[l]})`])) as S6;

